import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import path from 'node:path';

export const LIMITS = { title: 200, author: 200, notes: 10_000 };

// Checks and normalises form input for a new book.
// Returns { values, errors } where errors is empty when the input is valid.
export function validateBook(input) {
  const values = {
    title: String(input.title ?? '').trim(),
    author: String(input.author ?? '').trim(),
    notes: String(input.notes ?? '').trim(),
  };
  const errors = [];
  if (!values.title) errors.push('Title is required.');
  if (!values.author) errors.push('Author is required.');
  for (const [field, max] of Object.entries(LIMITS)) {
    if (values[field].length > max) errors.push(`${capitalise(field)} must be at most ${max} characters.`);
  }
  return { values, errors };
}

// Loads books from a JSON file and keeps them in memory. Every change is
// written back to disk (via a temp file + rename, so a crash mid-write can't
// leave a half-written file) before it becomes visible in memory.
export async function openStore(file) {
  let books = await load(file);
  let queue = Promise.resolve();

  // Runs changes one at a time so concurrent requests can't clobber each other.
  function update(change) {
    const result = queue.then(async () => {
      const { next, value } = change(books);
      await save(file, next);
      books = next;
      return value;
    });
    queue = result.catch(() => {});
    return result;
  }

  return {
    list: () => books,

    get: (id) => books.find((book) => book.id === id),

    add(values) {
      return update((current) => {
        const book = {
          id: newId(current),
          title: values.title,
          author: values.author,
          notes: values.notes,
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        return { next: [...current, book], value: book };
      });
    },

    // Resolves to the updated book, or undefined if there is no book with that id.
    finish(id) {
      return update((current) => {
        const existing = current.find((book) => book.id === id);
        if (!existing) return { next: current, value: undefined };
        if (existing.status === 'finished') return { next: current, value: existing };
        const book = { ...existing, status: 'finished', finishedAt: new Date().toISOString() };
        return { next: current.map((b) => (b.id === id ? book : b)), value: book };
      });
    },
  };
}

async function load(file) {
  let text;
  try {
    text = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // Refuse to start on a broken file rather than silently overwriting someone's reading list.
  let books;
  try {
    books = JSON.parse(text);
  } catch (err) {
    throw new Error(`${file} is not valid JSON (${err.message}). Fix or move it, then restart.`);
  }
  if (!Array.isArray(books)) {
    throw new Error(`${file} should contain a JSON array of books. Fix or move it, then restart.`);
  }
  return books;
}

async function save(file, books) {
  await mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + '\n');
  await rename(tmp, file);
}

// Short random ids, so a shared link doesn't reveal how many books there are
// or let someone guess the address of the next one.
function newId(books) {
  let id;
  do {
    id = randomBytes(6).toString('base64url');
  } while (books.some((book) => book.id === id));
  return id;
}

function capitalise(word) {
  return word[0].toUpperCase() + word.slice(1);
}

