import { LIMITS } from './store.js';

export function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

const e = escapeHtml;

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${e(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 { margin-bottom: 0.25rem; }
  h2 { margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: 0.25rem; }
  a { color: #1a5fb4; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
  .errors { color: #a00; }
  label { display: block; margin-top: 0.75rem; font-weight: 600; }
  input[type=text], textarea { width: 100%; box-sizing: border-box; padding: 0.4rem; font: inherit; }
  textarea { min-height: 6rem; }
  button { font: inherit; padding: 0.3rem 0.8rem; cursor: pointer; }
  form.add button { margin-top: 1rem; }
  .actions { display: flex; gap: 0.5rem; margin-top: 1.5rem; }
</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function finishButton(book, next) {
  return `<form method="post" action="/books/${e(book.id)}/finish">
    <input type="hidden" name="next" value="${e(next)}">
    <button type="submit">Mark finished</button>
  </form>`;
}

function bookLink(book) {
  return `<a href="/books/${e(book.id)}">${e(book.title)}</a> <span class="muted">by ${e(book.author)}</span>`;
}

export function homePage(books, { errors = [], values = {} } = {}) {
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingList = reading.length
    ? `<ul class="books">${reading
        .map((book) => `<li><span>${bookLink(book)}</span>${finishButton(book, '/')}</li>`)
        .join('')}</ul>`
    : `<p class="muted">Nothing on the go right now.</p>`;

  const finishedList = finished.length
    ? `<ul class="books">${finished
        .map((book) => `<li><span>${bookLink(book)}</span><span class="muted">${formatDate(book.finishedAt)}</span></li>`)
        .join('')}</ul>`
    : `<p class="muted">No finished books yet.</p>`;

  const errorList = errors.length
    ? `<ul class="errors">${errors.map((msg) => `<li>${e(msg)}</li>`).join('')}</ul>`
    : '';

  return layout(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${readingList}

<h2>Finished</h2>
${finishedList}

<h2 id="add">Add a book</h2>
${errorList}
<form class="add" method="post" action="/books">
  <label for="title">Title</label>
  <input type="text" id="title" name="title" required maxlength="${LIMITS.title}" value="${e(values.title ?? '')}">
  <label for="author">Author</label>
  <input type="text" id="author" name="author" required maxlength="${LIMITS.author}" value="${e(values.author ?? '')}">
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes" maxlength="${LIMITS.notes}">${e(values.notes ?? '')}</textarea>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === 'finished'
      ? `Finished ${formatDate(book.finishedAt)}`
      : `Reading since ${formatDate(book.addedAt)}`;

  const notes = book.notes
    ? `<div class="notes">${e(book.notes)}</div>`
    : `<p class="muted">No notes.</p>`;

  return layout(
    `${book.title} by ${book.author}`,
    `<p><a href="/">&larr; All books</a></p>
<h1>${e(book.title)}</h1>
<p>by ${e(book.author)}</p>
<p class="muted">${status}</p>

<h2>Notes</h2>
${notes}

<div class="actions">
  ${book.status === 'reading' ? finishButton(book, `/books/${book.id}`) : ''}
  <button type="button" id="copy-link">Copy link to this book</button>
</div>
<script>
  document.getElementById('copy-link').addEventListener('click', async (event) => {
    const button = event.currentTarget;
    try {
      await navigator.clipboard.writeText(location.href);
      button.textContent = 'Link copied';
    } catch {
      prompt('Copy this link:', location.href);
    }
  });
</script>`,
  );
}

export function notFoundPage() {
  return layout(
    'Not found',
    `<h1>Not found</h1>
<p>There's no book at this address. It may have been a mistyped link.</p>
<p><a href="/">Go to all books</a></p>`,
  );
}

