  return http.createServer(async (req, res) => {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err.statusCode === 413) {
        send(res, 413, 'text/plain', 'Request too large');
        return;
      }
      console.error(err);
      if (!res.headersSent) send(res, 500, 'text/plain', 'Something went wrong');
      else res.end();
    }
  });
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
  const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);

  if (pathname === '/' && req.method === 'GET') {
    return send(res, 200, 'text/html', homePage(store.list()));
  }

  if (pathname === '/books' && req.method === 'POST') {
    const { values, errors } = validateBook(await readForm(req));
    if (errors.length) {
      return send(res, 400, 'text/html', homePage(store.list(), { errors, values }));
    }
    const book = await store.add(values);
    return redirect(res, `/books/${book.id}`);
  }

  if (bookMatch && req.method === 'GET') {
    const book = store.get(bookMatch[1]);
    if (!book) return send(res, 404, 'text/html', notFoundPage());
    return send(res, 200, 'text/html', bookPage(book));
  }

  if (finishMatch && req.method === 'POST') {
    const id = finishMatch[1];
    const form = await readForm(req);
    const book = await store.finish(id);
    if (!book) return send(res, 404, 'text/html', notFoundPage());
    // Only ever send people back to the list or this book's page.
    return redirect(res, form.next === `/books/${id}` ? form.next : '/');
  }

