import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { openStore } from '../src/store.js';
import { createServer } from '../src/server.js';

let dir, file, server, base;

async function start() {
  const store = await openStore(file);
  server = createServer(store);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((resolve) => server.close(resolve));
}

function post(pathname, fields) {
  return fetch(base + pathname, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  return res.headers.get('location');
}

// The HTML between the <h2> for a section and the next <h2>.
function section(html, heading) {
  return html.split(`<h2>${heading}</h2>`)[1].split('<h2')[0];
}

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), 'books-'));
  file = path.join(dir, 'data', 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty sections and the add form on a fresh start', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
    expect(html).toContain('<form class="add" method="post" action="/books">');
  });

  it('adds a book and redirects to its own page', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.\nWorms.' });
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const html = await (await fetch(base + location)).text();
    expect(html).toContain('<h1>Dune</h1>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Spice.\nWorms.');
    expect(html).toContain('Mark finished');

    const home = await (await fetch(base + '/')).text();
    expect(section(home, 'Currently reading')).toContain(`<a href="${location}">Dune</a>`);
    expect(section(home, 'Finished')).not.toContain('Dune');
  });

  it('moves a book to finished when marked finished', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' });

    const res = await post(`${location}/finish`, { next: '/' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    expect(section(home, 'Currently reading')).not.toContain('Dune');
    expect(section(home, 'Finished')).toContain('Dune');

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('Finished ');
    expect(page).not.toContain('Mark finished');
  });

  it('returns to the book page when finished from there, and nowhere else', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert' });
    let res = await post(`${location}/finish`, { next: location });
    expect(res.headers.get('location')).toBe(location);

    const other = await addBook({ title: 'Emma', author: 'Jane Austen' });
    res = await post(`${other}/finish`, { next: 'https://evil.example/' });
    expect(res.headers.get('location')).toBe('/');
  });

  it('keeps books after a restart', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Good.' });
    await post(`${location}/finish`, {});

    await stop();
    await start();

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('<h1>Dune</h1>');
    expect(page).toContain('Good.');
    expect(page).toContain('Finished ');

    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved).toHaveLength(1);
    expect(saved[0]).toMatchObject({ title: 'Dune', author: 'Frank Herbert', status: 'finished' });
  });

  it('rejects a book without a title or author and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: '', notes: 'my notes' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('Author is required.');
    expect(html).toContain('>my notes</textarea>');

    const home = await (await fetch(base + '/')).text();
    expect(home).toContain('Nothing on the go right now.');
  });

  it('escapes HTML in book details', async () => {
    const location = await addBook({ title: '<script>alert(1)</script>', author: 'A "B" & C', notes: '<img src=x>' });
    const html = await (await fetch(base + location)).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).not.toContain('<img src=x>');
    expect(html).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).toContain('A &quot;B&quot; &amp; C');
  });

  it('shows a not found page for unknown books', async () => {
    expect((await fetch(base + '/books/nope')).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
    expect((await fetch(base + '/elsewhere')).status).toBe(404);
  });

  it('rejects oversized requests', async () => {
    const res = await post('/books', { title: 'x', author: 'y', notes: 'z'.repeat(100_000) });
    expect(res.status).toBe(413);
  });

  it('handles books added at the same time without losing any', async () => {
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => post('/books', { title: `Book ${i}`, author: 'Someone' })),
    );
    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved).toHaveLength(20);
  });
});

describe('store', () => {
  it('refuses to start on a corrupt file instead of overwriting it', async () => {
    const broken = path.join(dir, 'broken.json');
    await writeFile(broken, '{ not json');
    await expect(openStore(broken)).rejects.toThrow(/not valid JSON/);
    expect(await readFile(broken, 'utf8')).toBe('{ not json');
  });
});

